  1	'use client';
  2	import * as React from 'react';
  3	import { useStableCallback } from '@base-ui/utils/useStableCallback';
  4	import { EMPTY_OBJECT } from '@base-ui/utils/empty';
  5	import {
  6	  createGenericEventDetails,
  7	  type BaseUIGenericEventDetails,
  8	} from '../internals/createBaseUIEventDetails';
  9	import { REASONS } from '../internals/reasons';
 10	import type { BaseUIComponentProps } from '../internals/types';
 11	import { FormContext } from '../internals/form-context/FormContext';
 12	import { useRenderElement } from '../internals/useRenderElement';
 13	import { useValueChanged } from '../internals/useValueChanged';
 14	
 15	/**
 16	 * A native form element with consolidated error handling.
 17	 * Renders a `<form>` element.
 18	 *
 19	 * Documentation: [Base UI Form](https://base-ui.com/react/components/form)
 20	 */
 21	export const Form = React.forwardRef(function Form<
 22	  FormValues extends Record<string, any> = Record<string, any>,
 23	>(componentProps: Form.Props<FormValues>, forwardedRef: React.ForwardedRef<HTMLFormElement>) {
 24	  const {
 25	    render,
 26	    className,
 27	    validationMode = 'onSubmit',
 28	    errors: externalErrors,
 29	    onSubmit,
 30	    onFormSubmit,
 31	    actionsRef,
 32	    style,
 33	    ...elementProps
 34	  } = componentProps;
 35	
 36	  const formRef = React.useRef<FormContext['formRef']['current']>({
 37	    fields: new Map(),
 38	  });
 39	  const elementRef = React.useRef<HTMLFormElement>(null);
 40	  const submittedRef = React.useRef(false);
 41	  const submitAttemptedRef = React.useRef(false);
 42	
 43	  const focusFirstInvalid = useStableCallback(() => {
 44	    // A field can be invalid without a focusable control (for example a checkbox group whose
 45	    // custom validation failed while every checkbox is unmounted, disabled, or reassociated).
 46	    // Keep submission blocked, but move focus to the first invalid field that has a usable control.
 47	    // Registration order can diverge from DOM order (keyed fields reordered without
 48	    // remounting, portals), so pick the first control by document position. For controls
 49	    // in disconnected trees (e.g. separate shadow roots), where document position is
 50	    // implementation-specific, keep registration order.
 51	    let hasInvalid = false;
 52	    let firstControl: HTMLElement | null = null;
 53	    for (const field of formRef.current.fields.values()) {
 54	      if (field.validityData.state.valid !== false) {
 55	        continue;
 56	      }
 57	      hasInvalid = true;
 58	      const control = field.controlRef.current;
 59	      if (control && (!firstControl || comesBeforeInSameTree(control, firstControl))) {
 60	        firstControl = control;
 61	      }
 62	    }
 63	    if (firstControl) {
 64	      firstControl.focus();
 65	      if (firstControl.tagName === 'INPUT') {
 66	        (firstControl as HTMLInputElement).select();
 67	      }
 68	      return true;
 69	    }
 70	    return hasInvalid;
 71	  });
 72	
 73	  const [errors, setErrors] = React.useState(externalErrors);
 74	
 75	  useValueChanged(externalErrors, () => {
 76	    setErrors(externalErrors);
 77	  });
 78	
 79	  React.useEffect(() => {
 80	    if (!submittedRef.current) {
 81	      return;
 82	    }
 83	
 84	    submittedRef.current = false;
 85	    focusFirstInvalid();
 86	  }, [errors, focusFirstInvalid]);
 87	
 88	  React.useImperativeHandle(
 89	    actionsRef,
 90	    () => ({
 91	      validate(fieldName?: string) {
 92	        if (fieldName) {
 93	          Array.from(formRef.current.fields.values())
 94	            .find((field) => field.name === fieldName)
 95	            ?.validate();
 96	        } else {
 97	          formRef.current.fields.forEach((field) => {
 98	            field.validate();
 99	          });
100	        }
101	      },
102	    }),
103	    [],
104	  );
105	
106	  const element = useRenderElement('form', componentProps, {
107	    ref: [forwardedRef, elementRef],
108	    props: [
109	      {
110	        noValidate: true,
111	        onSubmit(event) {
112	          submitAttemptedRef.current = true;
113	
114	          // Async validation isn't supported to stop the submit event.
115	          formRef.current.fields.forEach((field) => {
116	            field.validate();
117	          });
118	
119	          if (focusFirstInvalid()) {
120	            event.preventDefault();
121	            return;
122	          }
123	
124	          submittedRef.current = true;
125	          onSubmit?.(event as any);
126	
127	          if (onFormSubmit) {
128	            event.preventDefault();
129	
130	            const formValues = {} as FormValues;
131	            formRef.current.fields.forEach((field) => {
132	              if (field.name) {
133	                (formValues as Record<string, any>)[field.name] = field.getValue();
134	              }
135	            });
136	
137	            onFormSubmit(formValues, createGenericEventDetails(REASONS.none, event.nativeEvent));
138	          }
139	        },
140	      },
141	      elementProps,
142	    ],
143	  });
144	
145	  const clearErrors = useStableCallback((name: string | undefined) => {
146	    if (!name) {
147	      return;
148	    }
149	    setErrors((previousErrors) => {
150	      if (!previousErrors || !Object.hasOwn(previousErrors, name)) {
151	        return previousErrors;
152	      }
153	      const nextErrors = { ...previousErrors };
154	      delete nextErrors[name];
155	      return nextErrors;
156	    });
157	  });
158	
159	  const contextValue: FormContext = React.useMemo(
160	    () => ({
161	      elementRef,
162	      formRef,
163	      validationMode,
164	      errors: errors ?? EMPTY_OBJECT,
165	      clearErrors,
166	      submitAttemptedRef,
167	    }),
168	    [formRef, validationMode, errors, clearErrors],
169	  );
170	
171	  return <FormContext.Provider value={contextValue}>{element}</FormContext.Provider>;
172	}) as {
173	  <FormValues extends Record<string, any> = Record<string, any>>(
174	    props: Form.Props<FormValues> & {
175	      ref?: React.Ref<HTMLFormElement> | undefined;
176	    },
177	  ): React.JSX.Element;
178	};
179	
180	export type FormSubmitEventReason = typeof REASONS.none;
181	export type FormSubmitEventDetails = BaseUIGenericEventDetails<Form.SubmitEventReason>;
182	
183	export type FormValidationMode = 'onSubmit' | 'onBlur' | 'onChange';
184	
185	export interface FormActions {
186	  validate: (fieldName?: string | undefined) => void;
187	}
188	
189	export interface FormState {}
190	
191	export interface FormProps<
192	  FormValues extends Record<string, any> = Record<string, any>,
193	> extends BaseUIComponentProps<'form', FormState, React.ComponentPropsWithRef<'form'>> {
194	  /**
195	   * Determines when the form should be validated.
196	   * The `validationMode` prop on `<Field.Root>` takes precedence over this.
197	   *
198	   * - `onSubmit` (default): validates the field when the form is submitted, afterwards fields will re-validate on change.
199	   * - `onBlur`: validates a field when it loses focus.
200	   * - `onChange`: validates the field on every change to its value.
201	   *
202	   * @default 'onSubmit'
203	   */
204	  validationMode?: FormValidationMode | undefined;
205	  /**
206	   * Validation errors returned externally, typically after submission by a server or a form action.
207	   * This should be an object where keys correspond to the `name` attribute on `<Field.Root>`,
208	   * and values correspond to error(s) related to that field.
209	   */
210	  errors?: FormContext['errors'] | undefined;
211	  /**
212	   * Event handler called when the form is submitted.
213	   * `preventDefault()` is called on the native submit event when used.
214	   */
215	  onFormSubmit?:
216	    | ((formValues: FormValues, eventDetails: Form.SubmitEventDetails) => void)
217	    | undefined;
218	  /**
219	   * A ref to imperative actions.
220	   * - `validate`: Validates all fields when called. Optionally pass a field name to validate a single field.
221	   * @example
222	   * ```tsx
223	   * // validate all fields
224	   * actionsRef.current?.validate();
225	   *
226	   * // validate one field
227	   * actionsRef.current?.validate('email');
228	   * ```
229	   */
230	  actionsRef?: React.RefObject<Form.Actions | null> | undefined;
231	}
232	
233	export namespace Form {
234	  export type Props<FormValues extends Record<string, any> = Record<string, any>> =
235	    FormProps<FormValues>;
236	  export type State = FormState;
237	  export type Actions = FormActions;
238	  export type ValidationMode = FormValidationMode;
239	  export type SubmitEventReason = FormSubmitEventReason;
240	  export type SubmitEventDetails = FormSubmitEventDetails;
241	
242	  export type Values<FormValues extends Record<string, any> = Record<string, any>> = FormValues;
243	}
244	
245	/* eslint-disable no-bitwise */
246	function comesBeforeInSameTree(element: Node, reference: Node) {
247	  const position = element.compareDocumentPosition(reference);
248	  return (
249	    (position & Node.DOCUMENT_POSITION_DISCONNECTED) === 0 &&
250	    (position & Node.DOCUMENT_POSITION_FOLLOWING) !== 0
251	  );
252	}

