 16	 * A native form element with consolidated error handling.
 17	 * Renders a `<form>` element.
 18	 *
 19	 * Documentation: [Base UI Form](https://base-ui.com/react/components/form)
 20	 */
 21	export const Form = React.forwardRef(function Form<
 22	  FormValues extends Record<string, any> = Record<string, any>,
 23	>(componentProps: Form.Props<FormValues>, forwardedRef: React.ForwardedRef<HTMLFormElement>) {
 24	  const {
 25	    render,
 26	    className,
 27	    validationMode = 'onSubmit',
 28	    errors: externalErrors,
 29	    onSubmit,
 30	    onFormSubmit,
 31	    actionsRef,
 32	    style,
 33	    ...elementProps
 34	  } = componentProps;
 35	
 36	  const formRef = React.useRef<FormContext['formRef']['current']>({
 37	    fields: new Map(),
 38	  });
 39	  const elementRef = React.useRef<HTMLFormElement>(null);
 40	  const submittedRef = React.useRef(false);
 41	  const submitAttemptedRef = React.useRef(false);
 42	
 43	  const focusFirstInvalid = useStableCallback(() => {
 44	    // A field can be invalid without a focusable control (for example a checkbox group whose
 45	    // custom validation failed while every checkbox is unmounted, disabled, or reassociated).
 46	    // Keep submission blocked, but move focus to the first invalid field that has a usable control.
 47	    // Registration order can diverge from DOM order (keyed fields reordered without
 48	    // remounting, portals), so pick the first control by document position. For controls
 49	    // in disconnected trees (e.g. separate shadow roots), where document position is
 50	    // implementation-specific, keep registration order.
 51	    let hasInvalid = false;
 52	    let firstControl: HTMLElement | null = null;
 53	    for (const field of formRef.current.fields.values()) {
 54	      if (field.validityData.state.valid !== false) {
 55	        continue;
 56	      }
 57	      hasInvalid = true;
 58	      const control = field.controlRef.current;
 59	      if (control && (!firstControl || comesBeforeInSameTree(control, firstControl))) {
 60	        firstControl = control;
 61	      }
 62	    }
 63	    if (firstControl) {
 64	      firstControl.focus();
 65	      if (firstControl.tagName === 'INPUT') {
 66	        (firstControl as HTMLInputElement).select();
 67	      }
 68	      return true;
 69	    }
 70	    return hasInvalid;
 71	  });
 72	
 73	  const [errors, setErrors] = React.useState(externalErrors);
 74	
 75	  useValueChanged(externalErrors, () => {
 76	    setErrors(externalErrors);
 77	  });
 78	
 79	  React.useEffect(() => {
 80	    if (!submittedRef.current) {
 81	      return;
 82	    }
 83	
 84	    submittedRef.current = false;
 85	    focusFirstInvalid();
 86	  }, [errors, focusFirstInvalid]);
 87	
 88	  React.useImperativeHandle(
 89	    actionsRef,
 90	    () => ({
 91	      validate(fieldName?: string) {
 92	        if (fieldName) {
 93	          Array.from(formRef.current.fields.values())
 94	            .find((field) => field.name === fieldName)
 95	            ?.validate();
 96	        } else {
 97	          formRef.current.fields.forEach((field) => {
 98	            field.validate();
 99	          });
100	        }
101	      },
102	    }),
103	    [],
104	  );
105	
106	  const element = useRenderElement('form', componentProps, {
107	    ref: [forwardedRef, elementRef],
108	    props: [
109	      {
110	        noValidate: true,
111	        onSubmit(event) {
