119	          if (focusFirstInvalid()) {
120	            event.preventDefault();
121	            return;
122	          }
123	
124	          submittedRef.current = true;
125	          onSubmit?.(event as any);
126	
127	          if (onFormSubmit) {
128	            event.preventDefault();
129	
130	            const formValues = {} as FormValues;
131	            formRef.current.fields.forEach((field) => {
132	              if (field.name) {
