137	            onFormSubmit(formValues, createGenericEventDetails(REASONS.none, event.nativeEvent));
138	          }
139	        },
140	      },
141	      elementProps,
142	    ],
143	  });
144	
145	  const clearErrors = useStableCallback((name: string | undefined) => {
146	    if (!name) {
147	      return;
148	    }
149	    setErrors((previousErrors) => {
150	      if (!previousErrors || !Object.hasOwn(previousErrors, name)) {
151	        return previousErrors;
152	      }
153	      const nextErrors = { ...previousErrors };
154	      delete nextErrors[name];
155	      return nextErrors;
156	    });
157	  });
158	
159	  const contextValue: FormContext = React.useMemo(
160	    () => ({
161	      elementRef,
162	      formRef,
163	      validationMode,
164	      errors: errors ?? EMPTY_OBJECT,
165	      clearErrors,
166	      submitAttemptedRef,
167	    }),
168	    [formRef, validationMode, errors, clearErrors],
169	  );
170	
171	  return <FormContext.Provider value={contextValue}>{element}</FormContext.Provider>;
172	}) as {
173	  <FormValues extends Record<string, any> = Record<string, any>>(
174	    props: Form.Props<FormValues> & {
175	      ref?: React.Ref<HTMLFormElement> | undefined;
176	    },
177	  ): React.JSX.Element;
178	};
179	
180	export type FormSubmitEventReason = typeof REASONS.none;
181	export type FormSubmitEventDetails = BaseUIGenericEventDetails<Form.SubmitEventReason>;
182	
183	export type FormValidationMode = 'onSubmit' | 'onBlur' | 'onChange';
184	
185	export interface FormActions {
186	  validate: (fieldName?: string | undefined) => void;
187	}
188	
189	export interface FormState {}
190	
191	export interface FormProps<
192	  FormValues extends Record<string, any> = Record<string, any>,
193	> extends BaseUIComponentProps<'form', FormState, React.ComponentPropsWithRef<'form'>> {
194	  /**
195	   * Determines when the form should be validated.
196	   * The `validationMode` prop on `<Field.Root>` takes precedence over this.
197	   *
198	   * - `onSubmit` (default): validates the field when the form is submitted, afterwards fields will re-validate on change.
199	   * - `onBlur`: validates a field when it loses focus.
200	   * - `onChange`: validates the field on every change to its value.
201	   *
202	   * @default 'onSubmit'
203	   */
204	  validationMode?: FormValidationMode | undefined;
205	  /**
206	   * Validation errors returned externally, typically after submission by a server or a form action.
207	   * This should be an object where keys correspond to the `name` attribute on `<Field.Root>`,
208	   * and values correspond to error(s) related to that field.
209	   */
210	  errors?: FormContext['errors'] | undefined;
211	  /**
212	   * Event handler called when the form is submitted.
213	   * `preventDefault()` is called on the native submit event when used.
214	   */
215	  onFormSubmit?:
216	    | ((formValues: FormValues, eventDetails: Form.SubmitEventDetails) => void)
217	    | undefined;
218	  /**
219	   * A ref to imperative actions.
220	   * - `validate`: Validates all fields when called. Optionally pass a field name to validate a single field.
221	   * @example
222	   * ```tsx
223	   * // validate all fields
224	   * actionsRef.current?.validate();
225	   *
226	   * // validate one field
227	   * actionsRef.current?.validate('email');
228	   * ```
229	   */
230	  actionsRef?: React.RefObject<Form.Actions | null> | undefined;
231	}
232	
233	export namespace Form {
234	  export type Props<FormValues extends Record<string, any> = Record<string, any>> =
235	    FormProps<FormValues>;
236	  export type State = FormState;
237	  export type Actions = FormActions;
238	  export type ValidationMode = FormValidationMode;
239	  export type SubmitEventReason = FormSubmitEventReason;
240	  export type SubmitEventDetails = FormSubmitEventDetails;
241	
242	  export type Values<FormValues extends Record<string, any> = Record<string, any>> = FormValues;
243	}
244	
245	/* eslint-disable no-bitwise */
246	function comesBeforeInSameTree(element: Node, reference: Node) {
247	  const position = element.compareDocumentPosition(reference);
248	  return (
249	    (position & Node.DOCUMENT_POSITION_DISCONNECTED) === 0 &&
250	    (position & Node.DOCUMENT_POSITION_FOLLOWING) !== 0
251	  );
252	}

