import * as React from 'react';
import { expect, vi, it, describe, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);

describe('probes', () => {
  it('A: clear after successful submit (default onSubmit mode, required)', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form onFormSubmit={() => setValue('')}>
          <Field.Root name="title" data-testid="root" validate={validate}>
            <Field.Control required value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole('textbox');
    fireEvent.change(control, { target: { value: 'buy milk' } });
    fireEvent.click(screen.getByText('submit'));
    await act(async () => {});
    const root = screen.getByTestId('root');
    console.log('A value:', JSON.stringify((control as HTMLInputElement).value),
      'invalid:', root.hasAttribute('data-invalid'), 'aria-invalid:', control.getAttribute('aria-invalid'),
      'error:', screen.queryByTestId('error')?.textContent, 'dirty', root.hasAttribute('data-dirty'),
      'validate calls', validate.mock.calls.length);
  });

  it('A2: async-loaded initial value marks dirty / validates in onChange', async () => {
    const validate = vi.fn((v: unknown) => (String(v).length < 20 ? 'too short' : null));
    function App() {
      const [value, setValue] = React.useState('');
      React.useEffect(() => {
        setValue('loaded');
      }, []);
      return (
        <Field.Root name="title" data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="error" />
        </Field.Root>
      );
    }
    render(<App />);
    await act(async () => {});
    const root = screen.getByTestId('root');
    console.log('A2 dirty', root.hasAttribute('data-dirty'), 'invalid', root.hasAttribute('data-invalid'),
      'error', screen.queryByTestId('error')?.textContent, 'touched', root.hasAttribute('data-touched'));
  });

  it('B: checkbox via Field.Control with value attr', async () => {
    const validate = vi.fn(() => null);
    render(
      <Form errors={{ agree: 'Server error' }}>
        <Field.Root name="agree" data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control type="checkbox" value="yes" required data-testid="cb" />
          <Field.Error data-testid="error" />
        </Field.Root>
      </Form>,
    );
