    render(
      <Form onFormSubmit={() => {}}>
        <Field.Root name="agree" data-testid="root">
          <Input type="checkbox" value="yes" required data-testid="cb" />
          <Field.Error data-testid="error" />
        </Field.Root>
        <button type="submit">submit</button>
      </Form>,
    );
    const cb = screen.getByTestId('cb') as HTMLInputElement;
    const root = screen.getByTestId('root');
    fireEvent.click(screen.getByText('submit'));
    await act(async () => {});
    console.log('B3 after submit invalid', root.hasAttribute('data-invalid'), 'error', screen.queryByTestId('error')?.textContent);
    fireEvent.click(cb);
    await act(async () => {});
    console.log('B3 after check: checked', cb.checked, 'invalid', root.hasAttribute('data-invalid'), 'aria-invalid', cb.getAttribute('aria-invalid'), 'error', screen.queryByTestId('error')?.textContent);
  });

  it('B4: native radios with value attrs, onChange validate', async () => {
    const validate = vi.fn(() => null);
    const onValueChange = vi.fn();
    render(
      <Field.Root name="plan" data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control type="radio" value="free" data-testid="free" onValueChange={onValueChange} />
        <Field.Control type="radio" value="pro" data-testid="pro" onValueChange={onValueChange} />
      </Field.Root>,
    );
    fireEvent.click(screen.getByTestId('pro'));
    await act(async () => {});
    console.log('B4 validate calls', validate.mock.calls.length, 'onValueChange calls', onValueChange.mock.calls.length);
  });

  it('K: value={null}', async () => {
    const validate = vi.fn(() => null);
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
    render(
      <Field.Root name="x" data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value={null as any} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    await act(async () => {});
    spy.mockRestore();
    console.log('K validate calls', validate.mock.calls.length, 'dirty', screen.getByTestId('root').hasAttribute('data-dirty'), 'filled', screen.getByTestId('root').hasAttribute('data-filled'));
  });

  it('S: controlled range slider via native input', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState(5);
      return (
        <Field.Root name="x" data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control type="range" value={value} onValueChange={(v) => setValue(Number(v))} data-testid="r" />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByTestId('r'), { target: { value: '7' } });
    await act(async () => {});
    console.log('S validate calls', validate.mock.calls.length, 'dirty', screen.getByTestId('root').hasAttribute('data-dirty'));
  });

  it('T: clear after submit with custom validate only (no required)', async () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form onFormSubmit={() => setValue('')}>
          <Field.Root name="title" data-testid="root" validate={(v) => (v ? null : 'Title is required')}>
            <Input value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole('textbox');
    fireEvent.change(control, { target: { value: 'buy milk' } });
    fireEvent.click(screen.getByText('submit'));
    await act(async () => {});
    console.log('T invalid', screen.getByTestId('root').hasAttribute('data-invalid'), 'error', screen.queryByTestId('error')?.textContent);
  });

  it('U: renders per keystroke after submit attempt in default mode', async () => {
    let renders = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form onFormSubmit={() => {}}>
          <Field.Root name="t" validate={() => null}>
            <Field.Control value={value} onValueChange={setValue} render={(props) => { renders += 1; return <input {...props} />; }} />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole('textbox');
    fireEvent.change(control, { target: { value: 'a' } });
    fireEvent.click(screen.getByText('submit'));
    await act(async () => {});
    fireEvent.change(control, { target: { value: 'ab' } });
    const base = renders;
    fireEvent.change(control, { target: { value: 'abc' } });
    fireEvent.change(control, { target: { value: 'abcd' } });
    console.log('U renders for 2 keystrokes', renders - base);
  });
});
